const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var houston = ee.Geometry.Point(-95.3698, 29.7604).buffer(10000); // 10km buffer around Houston center

  // Define time ranges
  var dec2012_start = '2012-12-01';
  var dec2012_end = '2012-12-31';
  var dec2013_start = '2013-12-01';
  var dec2013_end = '2013-12-31';
  var other_start = '2012-01-01';
  var other_end = '2014-12-31';

  // 2. Data Acquisition - VIIRS Monthly Nighttime Lights
  var viirs = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG')
    .select('avg_rad');

  // Get December 2012 and 2013 images
  var dec2012 = viirs.filterDate(dec2012_start, dec2012_end);
  var dec2013 = viirs.filterDate(dec2013_start, dec2013_end);
  var decembers = dec2012.merge(dec2013);

  // Get other months (2012-2014, exclude Dec 2012 and Dec 2013)
  var otherMonths = viirs.filterDate(other_start, other_end)
    .filter(ee.Filter.calendarRange(1, 11, 'month')) // Exclude December (month=12)
    .merge(viirs.filterDate('2014-12-01', '2014-12-31')); // Include Dec 2014

  // 3. Check collection sizes
  var decSize = decembers.size().getInfo();
  var otherSize = otherMonths.size().getInfo();

  console.log('December 2012/2013 images:', decSize);
  console.log('Other months images:', otherSize);

  if (decSize === 0 || otherSize === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Compute mean radiance for each set
  // For Decembers: average of the two months
  var decMeanImg = decembers.mean();
  // For other months: average across all images
  var otherMeanImg = otherMonths.mean();

  // Reduce regions
  var decStats = decMeanImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: houston,
    scale: 1000,
    maxPixels: 1e9
  });
  var otherStats = otherMeanImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: houston,
    scale: 1000,
    maxPixels: 1e9
  });

  var decRad = decStats.get('avg_rad').getInfo();
  var otherRad = otherStats.get('avg_rad').getInfo();

  // Also get pixel counts to check for valid data
  var decCount = decMeanImg.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: houston,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();
  var otherCount = otherMeanImg.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: houston,
    scale: 1000,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  console.log('December avg radiance:', decRad, 'Valid pixels:', decCount);
  console.log('Other months avg radiance:', otherRad, 'Valid pixels:', otherCount);

  // 5. Validation
  if (decCount === 0 || otherCount === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  if (decRad === null || otherRad === null || 
      isNaN(decRad) || isNaN(otherRad) ||
      decRad < 0 || otherRad < 0) { // Radiance should be non-negative
    console.log('<answer>C3</answer>');
    return;
  }

  // 6. Comparison and final answer
  var isHigher = decRad > otherRad;
  console.log('December > Other months?', isHigher);

  if (isHigher) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
